g=[[0]*15 for _ in range(15)]
for r in range(2,11): g[r][3]=g[r][11]=3
for c in range(3,12): g[2][c]=g[10][c]=3
for r in range(3,10):
    for c in range(4,11):
        if (r,c)==(5,4): g[r][c]=3; continue
        d=max(abs(r-5),abs(c-4))
        g[r][c]=4 if d%2==1 else 2
for row in g: print(''.join(map(str,row)))
